STARTUP_SOURCE='#!/usr/bin/env python3\n"""Explicitly invoked, aggregate-only read-only startup snapshot. Never imports backend.\nNo service actions, source/config changes, DDL, row locks, repairs, or DB commits.\nUse python3 -B runner.py under an independently authorized existing runtime environment.\nThis does not assert a maintenance boundary or authorize installation.\n"""\nimport sys\nsys.dont_write_bytecode = True\nimport ast\nfrom collections import Counter\nfrom datetime import datetime, timezone\nimport hashlib\nimport json\nimport os\nimport re\nfrom pathlib import Path\nimport socket\nimport subprocess\nimport time\n\nHERE = Path(__file__).resolve().parent\nROOT = Path(\'/var/www/stroyka-app\')\nHOST = \'msk-1-vm-zh4n\'\nPLAN_SHA = \'3062c8ac9d1aeef84759c250040b115c5e84e3144971b7af76dd4fea052fff85\'\nJSON_GUARD_SHA = \'a3eeddd131684baf80972483bc657701a16d092746bb1a0057258ace7d87e0d0\'\nY_HASH = \'f0854c841bb5bed487a6c96657cb6a36e6c09690533b0c6dfbd8768c9482e61a\'\nINDEX_HASH = \'fa1e3e2f71ad5c764df583811f0fc08d37161f401f8fdbba393368b13b2c1c07\'\nTARGETS = (\'ai_tasks\',\'brigade_contracts\',\'brigade_payments\',\'companies\',\'company_requisites\',\n \'estimates\',\'expenses\',\'material_norms\',\'material_transfers\',\'own_expenses\',\'platform_accounts\',\n \'project_payments\',\'site_price_rules\',\'unexpected_works\',\'user_company_roles\',\'users\',\'warehouse_movements\')\nRELATIONS = tuple(sorted((*TARGETS,\'ai_findings\',\'projects\')))\nSEED_TARGETS = (\'platform_accounts\',\'companies\',\'user_company_roles\',\'users\',\'site_price_rules\',\'material_norms\')\nINSERT_TARGETS = frozenset((*SEED_TARGETS,\'expenses\'))\nUPDATE_TARGETS = frozenset(TARGETS)-frozenset((\'platform_accounts\',\'user_company_roles\',\'site_price_rules\',\'material_norms\'))\nROLES = (\'директор\',\'зам_директора\',\'бухгалтер\',\'system_owner\',\'platform_admin\',\'platform_support\',\'billing_admin\',\'account_owner\',\'account_admin\')\n\nTOTAL_SECONDS = 120\nMAX_JSON_ROWS = 50000\nMAX_JSON_VALUE_BYTES = 2 * 1024 * 1024\nMAX_JSON_TOTAL_BYTES = 32 * 1024 * 1024\n\nclass CheckError(Exception):\n    def __init__(self, code, counts=None):\n        super().__init__(code)\n        self.counts = counts or {}\n\nclass Budget:\n    def __init__(self):\n        self.deadline = time.monotonic() + TOTAL_SECONDS\n    def milliseconds(self):\n        remaining = self.deadline-time.monotonic()\n        if remaining <= 0:\n            raise CheckError(\'TOTAL_DEADLINE_EXCEEDED\')\n        return max(1,min(30000,int(remaining*1000)))\n    def configure(self, cursor):\n        cursor.execute(\'SET LOCAL statement_timeout = %s\',(str(self.milliseconds())+\'ms\',))\n        self.milliseconds()\n    def execute(self, cursor, sql, params=None):\n        self.configure(cursor)\n        cursor.execute(sql,params)\n        self.milliseconds()\n\n\ndef require(value, code):\n    if not value:\n        raise CheckError(code)\n\ndef sha(data):\n    return hashlib.sha256(data).hexdigest()\n\ndef load_plan():\n    raw = EMBEDDED_PLAN.encode()\n    require(sha(raw)==PLAN_SHA,\'AUDITED_PLAN_CHANGED\')\n    require(sha(EMBEDDED_ESTIMATE.encode())==JSON_GUARD_SHA,\'JSON_GUARD_CHANGED\')\n    plan=json.loads(raw)\n    require(len(plan[\'guards\'])==31,\'AUDITED_GUARD_COUNT_CHANGED\')\n    return plan\n\ndef check_baseline(root, plan):\n    require(root.resolve()==root,\'ROOT_SYMLINK\')\n    for relative, expected in (\n        (\'backend/main.py\',plan[\'baseline_main_sha256\']),\n        (\'backend/features/model_gateway/yandex_adapter.py\',Y_HASH),(\'build/index.html\',INDEX_HASH)):\n        path=root/relative\n        require(path.is_file() and not path.is_symlink(),\'BASELINE_FILE_MISSING_OR_LINKED\')\n        require(sha(path.read_bytes())==expected,\'BASELINE_FILE_CHANGED\')\n    p=subprocess.run([\'git\',\'-c\',\'core.fsmonitor=false\',\'-C\',str(root),\'rev-parse\',\'HEAD\'],\n        env=dict(os.environ,GIT_OPTIONAL_LOCKS=\'0\'),capture_output=True,timeout=10,check=False)\n    require(p.returncode==0 and p.stdout.decode().strip()==plan[\'baseline_head\'],\'BASELINE_HEAD_CHANGED\')\n    tree=ast.parse((root/\'backend/main.py\').read_bytes())\n    found={}\n    for node in tree.body:\n        names=[node.name] if isinstance(node,ast.FunctionDef) else [n.id for n in node.targets if isinstance(n,ast.Name)] if isinstance(node,ast.Assign) else []\n        for name in names:\n            if name in plan[\'startup_ast_hashes\']:\n                found[name]=sha(ast.dump(node,include_attributes=False).encode())\n    require(found==plan[\'startup_ast_hashes\'],\'STARTUP_AST_CHANGED\')\n    return {\'head\':plan[\'baseline_head\'],\'main_sha256\':plan[\'baseline_main_sha256\'],\'startup_ast_matches_release\':True}\n\ndef connection_settings(env):\n    require(all(env.get(k) for k in (\'DB_NAME\',\'DB_USER\',\'DB_HOST\')),\'EXPLICIT_RUNTIME_DATABASE_SETTINGS_REQUIRED\')\n    require(env[\'DB_NAME\']==\'stroyka\',\'WRONG_DATABASE_NAME\')\n    return dict(dbname=env[\'DB_NAME\'],user=env[\'DB_USER\'],host=env[\'DB_HOST\'],\n        password=env.get(\'DB_PASSWORD\',\'\'),port=env.get(\'DB_PORT\',\'5432\'),connect_timeout=5,\n        application_name=\'stroyka-startup-readonly\')\n\ndef inspect_connection(conn, plan):\n    budget = Budget()\n    # Setting a transaction read-only is scoped to this inspection connection only.\n    conn.set_session(readonly=True,autocommit=False,isolation_level=\'REPEATABLE READ\')\n    from estimate_guard import classify\n    report={\'scope\':\'snapshot_only\',\'captured_at\':datetime.now(timezone.utc).isoformat(),\n            \'plan_sha256\':PLAN_SHA,\'counts\':{},\'catalog\':{},\'read_errors\':[]}\n    try:\n        with conn.cursor() as cur:\n            budget.execute(cur,"SET LOCAL lock_timeout=\'3s\'")\n            budget.execute(cur,\'SHOW transaction_read_only\')\n            require(cur.fetchone()[0]==\'on\',\'READ_ONLY_TRANSACTION_REQUIRED\')\n            budget.execute(cur,"SELECT current_database(),current_setting(\'server_version_num\')::int,pg_is_in_recovery(),current_schemas(true),current_setting(\'server_encoding\')")\n            db,version,replica,schemas,encoding=cur.fetchone()\n            require(db==\'stroyka\' and 160000<=version<170000 and not replica and encoding==\'UTF8\',\'UNEXPECTED_DATABASE_IDENTITY\')\n            report[\'postgres_major\']=16\n            budget.execute(cur,\'SELECT current_database(),current_user,inet_server_addr()::text,inet_server_port()\')\n            report[\'database_identity_sha256\']=sha(json.dumps(cur.fetchone(),separators=(\',\',\':\')).encode())\n            # Observe existing startup resolution BEFORE setting our own deterministic lookup.\n            budget.execute(cur,"""SELECT c.relname,c.relkind,c.relrowsecurity,c.relforcerowsecurity,\n                to_regclass(c.relname)=c.oid FROM pg_catalog.pg_class c\n                JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace\n                WHERE n.nspname=\'public\' AND c.relname=ANY(%s) ORDER BY c.relname""",(list(RELATIONS),))\n            relations=cur.fetchall()\n            require({r[0] for r in relations}==set(RELATIONS),\'REQUIRED_RELATION_MISSING\')\n            require(all(r[1]==\'r\' and not r[2] and not r[3] and r[4] for r in relations),\'RELATION_VISIBILITY_OR_ROUTING_REVIEW\')\n            require(schemas and schemas[0]==\'pg_catalog\',\'STARTUP_FUNCTION_RESOLUTION_REVIEW\')\n            budget.execute(cur,"SET LOCAL search_path=pg_catalog,public")\n            budget.execute(cur,"""SELECT count(*) FROM pg_catalog.pg_inherits i\n                WHERE i.inhparent IN (SELECT c.oid FROM pg_catalog.pg_class c\n                    JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace\n                    WHERE n.nspname=\'public\' AND c.relname=ANY(%s))\n                   OR i.inhrelid IN (SELECT c.oid FROM pg_catalog.pg_class c\n                    JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace\n                    WHERE n.nspname=\'public\' AND c.relname=ANY(%s))""",(list(RELATIONS),list(RELATIONS)))\n            inheritance_count=cur.fetchone()[0]\n            if inheritance_count:\n                raise CheckError(\'AUDITED_RELATION_INHERITANCE_PRESENT\',{\'inheritance_edges\':inheritance_count})\n            report[\'catalog\'][\'inheritance_edges\']=0\n            budget.execute(cur,\'SELECT version_num FROM public.alembic_version ORDER BY version_num\')\n            require(cur.fetchall()==[(\'0102_job_candidates\',)],\'MIGRATION_BASELINE_CHANGED\')\n            for guard in plan[\'guards\']:\n                budget.execute(cur,guard[\'sql\'])\n                count=cur.fetchone()[0]\n                require(type(count) is int and count>=0,\'INVALID_COUNT_RESULT\')\n                report[\'counts\'][guard[\'id\']]=count\n            summary=Counter({\'noop\':0,\'would_update\':0,\'startup_error\':0})\n            # Size/row metadata first, in the SAME repeatable-read snapshot. Never\n            # transfer or parse an oversized value merely to discover its size.\n            budget.execute(cur,"""SELECT count(*),COALESCE(sum(octet_length(sections_json)),0),\n                COALESCE(max(octet_length(sections_json)),0) FROM public.estimates\n                WHERE sections_json IS NOT NULL AND sections_json<>\'\'""")\n            row_count,total_bytes,max_bytes=map(int,cur.fetchone())\n            sizes={\'json_rows\':row_count,\'json_total_bytes\':total_bytes,\'json_max_value_bytes\':max_bytes}\n            if row_count>MAX_JSON_ROWS or total_bytes>MAX_JSON_TOTAL_BYTES or max_bytes>MAX_JSON_VALUE_BYTES:\n                raise CheckError(\'JSON_SCAN_BUDGET_EXCEEDED\',sizes)\n            report[\'json_scan_sizes\']=sizes\n            seen=transferred=0\n            with conn.cursor(name=\'startup_estimates_readonly\') as stream:\n                # SET must use the ordinary control cursor, never an already-declared\n                # named cursor. CASE is defense in depth against oversized transfer.\n                budget.configure(cur)\n                stream.execute("""SELECT CASE WHEN octet_length(sections_json)<=%s\n                    THEN sections_json ELSE NULL END,octet_length(sections_json)\n                    FROM public.estimates WHERE sections_json IS NOT NULL AND sections_json<>\'\'\n                    LIMIT %s""",(MAX_JSON_VALUE_BYTES,MAX_JSON_ROWS+1))\n                while True:\n                    budget.configure(cur)\n                    batch=stream.fetchmany(min(128,MAX_JSON_ROWS-seen+1))\n                    budget.milliseconds()\n                    if not batch:\n                        break\n                    for raw,size in batch:\n                        seen+=1;transferred+=size\n                        if raw is None or seen>MAX_JSON_ROWS or size>MAX_JSON_VALUE_BYTES or transferred>MAX_JSON_TOTAL_BYTES:\n                            raise CheckError(\'JSON_FETCH_BUDGET_EXCEEDED\',{\'json_rows\':seen,\'json_total_bytes\':transferred})\n                        budget.milliseconds()\n                        summary[classify(raw)]+=1\n                        budget.milliseconds()\n            require(seen==row_count and transferred==total_bytes,\'JSON_SNAPSHOT_SIZE_CHANGED\')\n            report[\'estimate_json\']=dict(summary)\n            budget.execute(cur,\'SELECT count(*) FROM public.users WHERE role=ANY(%s)\',(list(ROLES),))\n            report[\'bookkeeping\']={\'privileged_user_rows_first_update\':cur.fetchone()[0],\n                \'fixed_serial_default_attempts\':82,\'fixed_explicit_id_seed_attempts\':2,\'zero_physical_writes_claimed\':False}\n            budget.execute(cur,"""SELECT count(*) FROM public.users WHERE company_id IS NOT NULL\n                AND COALESCE(role,\'\')<>\'\' AND role NOT IN\n                (\'system_owner\',\'platform_admin\',\'platform_support\',\'billing_admin\',\'account_owner\',\'account_admin\')""")\n            report[\'bookkeeping\'][\'membership_conflict_insert_attempts\']=cur.fetchone()[0]\n            # Metadata only: do not emit function bodies, defaults, SQL text, or business rows.\n            budget.execute(cur,"""SELECT c.relname,t.tgname,t.tgtype,t.tgenabled,\n                pg_get_triggerdef(t.oid),pg_get_functiondef(t.tgfoid)\n                FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid\n                JOIN pg_namespace n ON n.oid=c.relnamespace\n                WHERE n.nspname=\'public\' AND c.relname=ANY(%s)\n                AND NOT t.tgisinternal AND t.tgenabled<>\'D\' ORDER BY c.relname,t.tgname""",(list(TARGETS),))\n            triggers=[]\n            for table,name,kind,enabled,definition,function in cur.fetchall():\n                row=bool(kind&1); before=bool(kind&2); insert=bool(kind&4); update=bool(kind&16)\n                relevant=((not row and ((insert and table in INSERT_TARGETS) or (update and table in UPDATE_TARGETS))) or (row and before and insert and table in SEED_TARGETS)\n                          or (row and update and table==\'users\' and report[\'bookkeeping\'][\'privileged_user_rows_first_update\']>0))\n                triggers.append({\'table\':table,\'name\':name,\'enabled\':enabled,\n                    \'review_required_if_guards_zero\':relevant,\n                    \'dormant_when_zero_match\':not relevant,\'definition_sha256\':sha((definition+\'\\n\'+function).encode())})\n            report[\'catalog\'][\'triggers\']=triggers\n            budget.execute(cur,"""SELECT c.relname,r.rulename,pg_get_ruledef(r.oid)\n                FROM pg_rewrite r JOIN pg_class c ON c.oid=r.ev_class\n                JOIN pg_namespace n ON n.oid=c.relnamespace\n                WHERE n.nspname=\'public\' AND c.relname=ANY(%s) ORDER BY c.relname,r.rulename""",(list(TARGETS),))\n            report[\'catalog\'][\'rules\']=[{\'table\':t,\'name\':n,\'sha256\':sha(d.encode())} for t,n,d in cur.fetchall()]\n            budget.execute(cur,"SELECT evtname,evtevent,evtenabled,pg_get_functiondef(evtfoid) FROM pg_event_trigger WHERE evtenabled<>\'D\' ORDER BY evtname")\n            report[\'catalog\'][\'event_triggers\']=[{\'name\':n,\'event\':e,\'enabled\':a,\'function_sha256\':sha(d.encode())} for n,e,a,d in cur.fetchall()]\n            budget.execute(cur,"""SELECT c.relname,a.attname,tn.nspname,typ.typname,a.attidentity,\n                pg_get_expr(d.adbin,d.adrelid),\n                COALESCE((SELECT array_agg(dep.refobjid::bigint ORDER BY dep.refobjid)\n                    FROM pg_depend dep JOIN pg_class sq ON sq.oid=dep.refobjid AND sq.relkind=\'S\'\n                    WHERE dep.classid=\'pg_attrdef\'::regclass AND dep.objid=d.oid\n                      AND dep.refclassid=\'pg_class\'::regclass),\'{}\'::bigint[]),\n                pg_get_serial_sequence(format(\'%%I.%%I\',n.nspname,c.relname),a.attname)::regclass::oid::bigint\n                FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid\n                JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_type typ ON typ.oid=a.atttypid\n                JOIN pg_namespace tn ON tn.oid=typ.typnamespace\n                LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum\n                WHERE n.nspname=\'public\' AND c.relname=ANY(%s) AND a.attnum>0 AND NOT a.attisdropped\n                  AND (d.oid IS NOT NULL OR a.attidentity<>\'\') ORDER BY c.relname,a.attnum""",(list(SEED_TARGETS),))\n            defaults=cur.fetchall()\n            report[\'catalog\'][\'seed_defaults_count\']=len(defaults)\n            report[\'catalog\'][\'seed_defaults_sha256\']=sha(json.dumps(defaults,ensure_ascii=False,separators=(\',\',\':\')).encode())\n            sequence_mappings=[];mapped={};unclassified=[]\n            for table,column,type_schema,column_type,identity,expression,dependencies,owned_oid in defaults:\n                direct_nextval=bool(expression and re.fullmatch(r"nextval\\(\'(?:[^\']|\'\')+\'::regclass\\)",expression))\n                if direct_nextval or (expression and re.search(r\'\\bnextval\\s*\\(\',expression)) or dependencies or owned_oid is not None or identity:\n                    # Pinned source declares all six seed IDs SERIAL INTEGER. Reject\n                    # cross-owned, custom/type-shifted, extra-column or identity variants.\n                    valid=(column==\'id\' and type_schema==\'pg_catalog\' and column_type==\'int4\'\n                        and not identity and direct_nextval and len(dependencies)==1\n                        and owned_oid is not None and dependencies[0]==owned_oid)\n                    if not valid:\n                        raise CheckError(\'SEED_SEQUENCE_MAPPING_UNVERIFIED\',{\'unverified_sequence_columns\':1})\n                    budget.execute(cur,"""SELECT ns.nspname,sq.relname,tn.nspname,typ.typname,\n                        dep.deptype,onsp.nspname,owner.relname,oa.attname,sq.relowner=owner.relowner\n                        FROM pg_class sq JOIN pg_namespace ns ON ns.oid=sq.relnamespace\n                        JOIN pg_sequence seq ON seq.seqrelid=sq.oid JOIN pg_type typ ON typ.oid=seq.seqtypid\n                        JOIN pg_namespace tn ON tn.oid=typ.typnamespace\n                        LEFT JOIN pg_depend dep ON dep.classid=\'pg_class\'::regclass AND dep.objid=sq.oid\n                            AND dep.refclassid=\'pg_class\'::regclass AND dep.deptype IN (\'a\',\'i\')\n                        LEFT JOIN pg_class owner ON owner.oid=dep.refobjid\n                        LEFT JOIN pg_namespace onsp ON onsp.oid=owner.relnamespace\n                        LEFT JOIN pg_attribute oa ON oa.attrelid=owner.oid AND oa.attnum=dep.refobjsubid\n                        WHERE sq.oid=%s AND sq.relkind=\'S\'""",(owned_oid,))\n                    owners=cur.fetchall()\n                    require(len(owners)==1,\'SEED_SEQUENCE_OWNERSHIP_UNVERIFIED\')\n                    ns,seqname,seqtype_schema,seqtype,deptype,owner_schema,owner_table,owner_column,same_owner=owners[0]\n                    require(ns==\'public\' and seqtype_schema==\'pg_catalog\' and seqtype==column_type\n                        and deptype==\'a\' and owner_schema==\'public\' and owner_table==table\n                        and owner_column==column and same_owner,\'SEED_SEQUENCE_OWNERSHIP_OR_TYPE_UNVERIFIED\')\n                    entry={\'table\':table,\'column\':column,\'sequence_schema\':ns,\'sequence_name\':seqname,\n                        \'sequence_oid\':owned_oid,\'column_type\':column_type,\'sequence_type\':seqtype,\n                        \'ownership\':\'auto_owned_by_exact_column\',\'default_dependency_matches\':True,\n                        \'default_invoked_by_seed\':table not in (\'platform_accounts\',\'companies\')}\n                    sequence_mappings.append(entry);mapped[table]=entry\n                elif not (expression and re.fullmatch(r"(?:now\\(\\)|(?:true|false|NULL|[-+]?\\d+(?:\\.\\d+)?)|(?:\'(?:[^\']|\'\')*\'::(?:text|character varying|jsonb|integer|numeric|double precision|boolean|timestamp without time zone|text\\[\\])))",expression)):\n                    unclassified.append({\'table\':table,\'column\':column,\'sha256\':sha((expression or \'\').encode())})\n            require(set(mapped)==set(SEED_TARGETS),\'SEED_SEQUENCE_MAPPING_MISSING\')\n            report[\'catalog\'][\'seed_sequence_mappings\']=sequence_mappings\n            report[\'catalog\'][\'unclassified_seed_defaults\']=unclassified\n            # Names and is_called are metadata, but raw sequence positions remain unreported.\n            sequences=[]\n            for table in (\'platform_accounts\',\'companies\'):\n                ns=mapped[table][\'sequence_schema\'];rel=mapped[table][\'sequence_name\']\n                ident=\'"\'+ns.replace(\'"\',\'""\')+\'"."\'+rel.replace(\'"\',\'""\')+\'"\'\n                budget.execute(cur,\'SELECT last_value,is_called FROM \'+ident)\n                value,called=cur.fetchone()\n                budget.execute(cur,\'SELECT seqincrement,seqmin,seqmax,seqcache,seqcycle FROM pg_sequence WHERE seqrelid=%s::regclass\',(ident,))\n                increment,minimum,maximum,cache,cycle=cur.fetchone()\n                budget.execute(cur,\'SELECT GREATEST(COALESCE(MAX(id),1),1) FROM public.\'+table)\n                target=cur.fetchone()[0]\n                sequences.append({\'table\':table,\'setval_logical_noop\':value==target and called,\n                    \'would_rewind\':value>target,\'is_called\':called,\'increment\':increment,\'cache\':cache,\n                    \'cycle\':cycle,\'target_within_bounds\':minimum<=target<maximum})\n            report[\'bookkeeping\'][\'explicit_setval\']=sequences\n            budget.execute(cur,"""SELECT backend_type,COALESCE(state,\'unknown\'),count(*)\n                FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid()\n                GROUP BY backend_type,state ORDER BY backend_type,state""")\n            report[\'other_db_sessions\']=[{\'backend_type\':k,\'state\':s,\'count\':n} for k,s,n in cur.fetchall()]\n            budget.execute(cur,\'SELECT count(*) FROM pg_prepared_xacts WHERE database=current_database()\')\n            report[\'prepared_transactions\']=cur.fetchone()[0]\n        budget.milliseconds()\n        report[\'business_guards_satisfied\']=not any(report[\'counts\'].values()) and not summary[\'would_update\'] and not summary[\'startup_error\']\n        report[\'maintenance_boundary_proven\']=False  # SQL snapshots cannot prove service/ingress exclusion.\n    finally:\n        conn.rollback()\n    # A delayed rollback must not turn an expired inspection into a success.\n    budget.milliseconds()\n    return report\n\ndef main():\n    conn=None\n    try:\n        require(len(sys.argv)==1,\'NO_RUNTIME_OVERRIDE_FLAGS\')\n        require(socket.gethostname().split(\'.\')[0]==HOST,\'WRONG_HOST\')\n        plan=load_plan()\n        baseline=check_baseline(ROOT,plan)\n        import psycopg2\n        conn=psycopg2.connect(**connection_settings(os.environ))\n        report=inspect_connection(conn,plan)\n        report[\'baseline\']=baseline\n        print(json.dumps(report,sort_keys=True,ensure_ascii=False))\n        return 0 if report[\'business_guards_satisfied\'] else 2\n    except Exception as exc:\n        # SQL errors can contain row contents/connection secrets: never print exception text.\n        code=str(exc) if isinstance(exc,CheckError) else \'READ_ONLY_INSPECTION_FAILED\'\n        print(json.dumps({\'scope\':\'snapshot_only\',\'error\':code,\'business_guards_satisfied\':False,\n            \'counts\':exc.counts if isinstance(exc,CheckError) else {}}))\n        return 2\n    finally:\n        if conn is not None:\n            conn.close()\n\n'
