EMBEDDED_ESTIMATE='"""Pure read-only predicate mirroring main.py:445-497; never imports backend.\nCall on each raw sections_json selected in the SAME protected preflight snapshot.\nNo SQL, file reads, writes, or app initialization occurs in this module.\n"""\nimport json\n\nRESOURCE_TYPES = frozenset((\'material\',\'материал\',\'materials\',\'материалы\',\'equipment\',\'оборудование\',\'delivery\',\'доставка\',\'transport\'))\nTOTAL_KEYS = (\'lineTotal\',\'currentTotal\',\'total\',\'sum\',\'amount\',\'totalSum\',\'totalMaterial\',\'materialTotal\',\'materialSum\')\n\ndef startup_num(value):\n    try:\n        return float(str(value if value is not None else 0).replace(\' \',\'\').replace(\',\',\'.\'))\n    except Exception:\n        return 0.0\n\ndef classify(raw_sections):\n    try:\n        sections = json.loads(raw_sections or \'[]\')\n    except Exception:\n        return \'noop\'  # Original startup also skips malformed JSON.\n    if not isinstance(sections,list):\n        return \'noop\'\n    changed = False\n    try:\n        for section in sections:\n            if not isinstance(section,dict):\n                continue\n            for item in section.get(\'items\') or []:\n                if not isinstance(item,dict):\n                    continue\n                raw = str(item.get(\'itemType\') or item.get(\'type\') or item.get(\'kind\') or \'\').strip().lower()\n                value = None\n                for key in TOTAL_KEYS:\n                    value = item.get(key)\n                    if value:\n                        break\n                line_total = startup_num(value)\n                if raw in RESOURCE_TYPES and (startup_num(item.get(\'quantity\')) < 0 or line_total < 0):\n                    changed = True\n    except Exception:\n        return \'startup_error\'  # A truthy non-iterable items value aborts original startup.\n    return \'would_update\' if changed else \'noop\'\n'

def startup_module():
    estimate=types.ModuleType('estimate_guard')
    exec(compile(EMBEDDED_ESTIMATE,'<pinned-estimate-guard>','exec'),estimate.__dict__)
    sys.modules['estimate_guard']=estimate
    module=types.ModuleType('pinned_startup')
    module.__dict__.update(__file__=__file__,EMBEDDED_PLAN=EMBEDDED_PLAN,EMBEDDED_ESTIMATE=EMBEDDED_ESTIMATE)
    exec(compile(STARTUP_SOURCE,'<pinned-readonly-startup>','exec'),module.__dict__)
    return module
def output(args):
    result=subprocess.run(args,capture_output=True,text=True,timeout=20,check=False,env=dict(os.environ,LC_ALL='C'))
    need(result.returncode==0 or (args[:2]==['systemctl','show'] and 'LoadState=not-found' in result.stdout),'READONLY_INVENTORY_COMMAND_FAILED')
    return result.stdout

def unit_report(unit):
    text=output(['systemctl','show',unit,'--no-pager',*[arg for key in SAFE_PROPERTIES for arg in ('-p',key)]])
    data=dict(line.split('=',1) for line in text.splitlines() if '=' in line)
    command=data.pop('ExecStart','')
    data['ExecStartSHA256']=hashlib.sha256(command.encode()).hexdigest()
    executable=re.search(r'(?:^|[ {;])path=([^ ;}]+)',command)
    data['Executable']=executable[1] if executable else None
    module=re.search(r'\bbackend\.features\.[A-Za-z0-9_.]+',command)
    data['KnownModule']=module[0] if module else None
    files={}
    for filename in [data.get('FragmentPath',''),*data.get('DropInPaths','').split()]:
        if filename:
            path=Path(filename)
            files[filename]=sha(path) if path.is_file() else None
    data['UnitFileSHA256']=files
    group=data.get('ControlGroup','')
    if group and group.startswith('/') and '..' not in Path(group).parts:
        root=Path('/sys/fs/cgroup')/group.lstrip('/')
        pids=set()
        for file in root.rglob('cgroup.procs'):
            pids.update(file.read_text().split())
        data['CGroupProcessCount']=len(pids)
    else:data['CGroupProcessCount']=0
    return data

def listeners(pid):
    root=Path('/proc')/str(pid);sockets=set()
    for descriptor in (root/'fd').iterdir():
        try:value=os.readlink(descriptor)
        except FileNotFoundError:continue
        match=re.fullmatch(r'socket:\[(\d+)\]',value)
        if match:sockets.add(match[1])
    result=[]
    for name,allowed in [('tcp',{'0100007F'}),('tcp6',{'0'*31+'1','0'*24+'01000000'})]:
        for line in (root/'net'/name).read_text().splitlines()[1:]:
            fields=line.split()
            if fields[3]=='0A' and fields[9] in sockets:
                address,port=fields[1].split(':')
                result.append({'family':name,'address_hex':address,'port':int(port,16),'loopback_only':address in allowed})
    return result

def launch_inventory(units):
    known={value.get('ControlGroup') for value in units.values() if value.get('ControlGroup')}
    extras=[]
    for process in Path('/proc').iterdir():
        if not process.name.isdigit() or int(process.name)==os.getpid():continue
        try:
            command=(process/'cmdline').read_bytes()
            if not any(x in command for x in (b'/var/www/stroyka-app',b'backend.features.',b'pg_dump',b'psql')):continue
            group=(process/'cgroup').read_text()
            if not any(group.rstrip().endswith(':'+x) for x in known):
                extras.append({'pid':int(process.name),'command_sha256':hashlib.sha256(command).hexdigest()})
        except (FileNotFoundError,ProcessLookupError):continue
    crons=[]
    paths=[Path('/etc/crontab'),*Path('/etc/cron.d').glob('*'),*Path('/var/spool/cron/crontabs').glob('*')]
    for path in paths:
        if path.is_file():
            raw=path.read_bytes()
            count=sum(bool(re.search(rb'stroyka|pg_dump|/var/www/',line,re.I)) for line in raw.splitlines() if not line.lstrip().startswith(b'#'))
            if count:crons.append({'path':str(path),'sha256':hashlib.sha256(raw).hexdigest(),'relevant_lines':count})
    return {'unclassified_processes':extras,'relevant_cron_files':crons}

"""Parse captured nginx -T output in memory; emit routing metadata, never raw config."""
import re
import shlex
from urllib.parse import urlsplit


def routing_facts(text):
    if len(text)>2*1024*1024:raise ValueError('NGINX_CONFIG_TOO_LARGE')
    lexer=shlex.shlex(text,posix=True,punctuation_chars='{};')
    lexer.whitespace_split=True;lexer.commenters='#'
    tokens=[]
    for token in lexer:
        tokens.extend(list(token) if token and all(c in '{};' for c in token) else [token])
    index=0
    def parse():
        nonlocal index
        nodes=[];head=[]
        while index<len(tokens):
            token=tokens[index];index+=1
            if token=='}':
                if head:raise ValueError('INVALID_NGINX_BLOCK')
                return nodes
            if token==';':nodes.append((head,None));head=[]
            elif token=='{':nodes.append((head,parse()));head=[]
            else:head.append(token)
        if head:raise ValueError('INCOMPLETE_NGINX_CONFIG')
        return nodes
    nodes=parse();result=[]
    def visit(nodes):
        for head,children in nodes:
            if head==['server'] and children is not None:
                names=[value for directive,_ in children if directive[:1]==['server_name'] for value in directive[1:]]
                if not {'stroyka26.pro','www.stroyka26.pro'}.intersection(names):continue
                record={'app_server':True,'listeners':[],'proxy_targets':[],'maintenance_return_codes':[],'dynamic_proxy_targets':0}
                for directive,_ in children:
                    if directive[:1]==['listen'] and len(directive)>1:record['listeners'].append(directive[1])
                def routes(children):
                    for directive,child in children:
                        if directive[:1]==['proxy_pass'] and len(directive)==2:
                            if '$' in directive[1]:record['dynamic_proxy_targets']+=1
                            else:
                                url=urlsplit(directive[1]);record['proxy_targets'].append({'scheme':url.scheme,'host':url.hostname,'port':url.port})
                        if directive[:1]==['return'] and len(directive)>1 and directive[1].isdigit():record['maintenance_return_codes'].append(int(directive[1]))
                        if child is not None:routes(child)
                routes(children);result.append(record)
            elif children is not None:visit(children)
    visit(nodes)
    return result


STAGE='START'

def systemd_rows(kind):
    need(kind in ('jobs','units'),'UNEXPECTED_SYSTEMD_INVENTORY')
    args=['systemctl','list-'+kind,'--no-pager','--plain','--no-legend']
    if kind=='units':args.extend(['--all','stroyka*'])
    raw=output(args).strip()
    empty='No jobs running.' if kind=='jobs' else 'No units found.'
    if not raw or raw==empty:return []
    rows=[]
    for line in raw.splitlines():
        fields=line.split()
        if kind=='jobs':
            need(len(fields)==4 and fields[0].isdigit() and int(fields[0])>0,
                 'UNRECOGNIZED_SYSTEMD_JOB_ROW')
            unit,action,state=fields[1:]
            need(re.fullmatch(r'[A-Za-z0-9_.@:\\-]+',unit)
                 and re.fullmatch(r'[a-z-]+',action) and state in ('running','waiting'),
                 'UNRECOGNIZED_SYSTEMD_JOB_ROW')
            rows.append({'unit':unit,'type':action,'state':state})
        else:
            need(len(fields)>=4 and re.fullmatch(r'[A-Za-z0-9_.@:\\-]+',fields[0])
                 and all(re.fullmatch(r'[a-z-]+',value) for value in fields[1:4]),
                 'UNRECOGNIZED_SYSTEMD_UNIT_ROW')
            rows.append(dict(zip(('unit','load','active','sub'),fields[:4])))
    return rows

def collect():
    global STAGE
    STAGE='SERVICE_BASELINE'
    need(len(sys.argv)==1,'NO_OVERRIDE_FLAGS')
    need(os.geteuid()==0 and socket.gethostname().split('.')[0]==HOST,'WRONG_PRODUCTION_HOST_OR_USER')
    need(ROOT.resolve()==ROOT and ROOT.is_dir(),'WRONG_ROOT')
    pid=output(['systemctl','show','stroyka.service','-p','MainPID','--value']).strip()
    need(pid.isdigit() and int(pid)>0,'RUNNING_BASELINE_REQUIRED')
    process=Path('/proc')/pid
    need((process/'cwd').resolve()==ROOT/'backend','SERVICE_CWD_CHANGED')
    exe=(process/'exe').resolve()
    need(exe==Path('/usr/bin/python3.12').resolve(),'SERVICE_INTERPRETER_CHANGED')
    argv0=(process/'cmdline').read_bytes().split(b'\0')[0].decode()
    python=Path(argv0)
    if not python.is_absolute():python=ROOT/'backend'/python
    need(re.fullmatch(r'python(?:[0-9]+(?:\.[0-9]+)*)?',python.name) and python.resolve()==exe,'SERVICE_PYTHON_UNVERIFIED')
    if Path(sys.executable).absolute()!=python.absolute():
        os.execv(python,[str(python),'-E','-B',str(Path(__file__).absolute())])
    report={'format':1,'read_only':True,'maintenance_boundary_proven':False,'installation_ready':False,'captured_at_unix':int(time.time())}
    STAGE='UNIT_INVENTORY'
    report['units']={unit:unit_report(unit) for unit in UNITS}
    STAGE='QUEUED_JOBS'
    report['jobs']=systemd_rows('jobs')
    STAGE='STROYKA_UNITS'
    report['stroyka_units']=systemd_rows('units')
    STAGE='BACKEND_LISTENERS'
    report['backend_listeners']=listeners(pid)
    STAGE='NGINX_ROUTING'
    report['nginx_routing']=routing_facts(output(['nginx','-T']))
    STAGE='LAUNCH_INVENTORY'
    report['launch_inventory']=launch_inventory(report['units'])
    STAGE='STARTUP_BASELINE'
    runner=startup_module();plan=runner.load_plan()
    report['baseline']=runner.check_baseline(ROOT,plan)
    git_env=dict(os.environ,GIT_OPTIONAL_LOCKS='0')
    def git(*args):
        result=subprocess.run(['git','-c','core.fsmonitor=false','-C',str(ROOT),*args],env=git_env,capture_output=True,text=True,timeout=15)
        need(result.returncode==0,'GIT_READ_FAILED');return result.stdout.strip()
    report['tracked_dirty_paths']=git('diff','--no-ext-diff','--no-textconv','--name-only','HEAD').splitlines()
    report['staged_paths']=git('diff','--no-ext-diff','--no-textconv','--cached','--name-only').splitlines()
    need(set(report['tracked_dirty_paths'])=={'backend/main.py','backend/features/model_gateway/yandex_adapter.py'} and not report['staged_paths'],'UNEXPECTED_TRACKED_STATE')
    need(sha(ROOT/'backend/features/model_gateway/yandex_adapter.py')==runner.Y_HASH,'YANDEX_PATCH_CHANGED')
    STAGE='REVIEWED_HELPERS'
    for name,expected in HELPERS.items():
        path=ROOT/'scripts'/name
        need(not path.is_symlink() and sha(path)==expected,'REVIEWED_HELPER_CHANGED')
    spec=importlib.util.spec_from_file_location('_reviewed_unified_release',ROOT/'scripts/unified_release.py')
    helper=importlib.util.module_from_spec(spec);spec.loader.exec_module(helper)
    STAGE='SERVICE_RUNTIME_ENVIRONMENT'
    env=helper.runtime_environment(ROOT,'stroyka.service')
    STAGE='POSTGRES_SNAPSHOT'
    import psycopg2
    conn=psycopg2.connect(**runner.connection_settings(env))
    try:report['startup']=runner.inspect_connection(conn,plan)
    finally:conn.close()
    report['operator_confirmation_still_required']='No other deployments, manual SQL, cron or app writers during the proposed maintenance window.'
    return report

def safe_error_counts(error):
    counts=getattr(error,'counts',None)
    if type(counts) is not dict:return {}
    return {key:counts[key] for key in ('json_rows','json_total_bytes','json_max_value_bytes')
            if type(counts.get(key)) is int and 0<=counts[key]<=9223372036854775807}

def main():
    try:
        report=collect();print(json.dumps(report,ensure_ascii=False,sort_keys=True,indent=2));return 0
    except Exception as error:
        code=str(error) if isinstance(error,Stop) or (type(error).__name__=='CheckError' and re.fullmatch(r'[A-Z][A-Z0-9_]+',str(error))) else type(error).__name__
        print(json.dumps({'read_only':True,'report_complete':False,'stage':STAGE,'code':code,'counts':safe_error_counts(error),'installation_ready':False}));return 1
if __name__=='__main__':raise SystemExit(main())
